// Report exactly what happened, including failures. Never fabricate success.
const body = $('Resolution Webhook').first().json.body;
const notification = $json;

let refund = null;
let verification = { verified: true, reason: 'No refund in this path' };
let assignment = null;

try { refund = $('Execute Refund').first().json; } catch (e) { refund = null; }
try { verification = $('Verify Refund').first().json; } catch (e) { /* escalation path */ }
try { assignment = $('Hand To Specialist').first().json.assignment; } catch (e) { assignment = null; }

const refundOk = body.action !== 'refund' || (refund && refund.success);

return [{
  json: {
    success: Boolean(refundOk),
    error: refundOk ? '' : 'Refund rejected by the payments boundary',
    action_id: body.action_id,
    status: refundOk ? 'executed' : 'failed',
    refund,
    verification,
    assignment,
    notification
  }
}];
